  } finally { connecting = false; }
}

Modify checkNatsHealth to verify both publish and subscribe:
async function checkNatsHealth() {
  try {
    const testId = `health-${Date.now()}`;
    const received = new Promise(resolve => {
      const sub = nc.subscribe(`health.${testId}`, () => {
        sub.unsubscribe();
        resolve(true);
      });
    });
    await nc.publish(`health.${testId}`, { ts: Date.now() });
    return (await Promise.race([received, Promise.resolve(false)])) ? 'ok' : 'down';
  } catch { return 'down'; }
}

Add connection checks before tests:
async function waitForConnection(checkFn, timeout = 5000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (await checkFn()) return;
    await new Promise(r => setTimeout(r, 100));
  }
  throw new Error('Connection timeout');
}
// Usage before tests:
await waitForConnection(() => nats.nc?.getServer() && redis.redisClient?.status === 'ready');

